INSERT INTO planning_run (id, user_id, language_profile_id, model_call_job_id, workflow_version)
SELECT #{id, jdbcType=OTHER},
       profile.user_id,
       profile.id,
       #{modelCallJobId, jdbcType=OTHER},
       #{workflowVersion, jdbcType=BIGINT}
FROM language_profile profile
JOIN model_call_job job ON job.id = #{modelCallJobId, jdbcType=OTHER}
WHERE profile.id = #{languageProfileId, jdbcType=OTHER}
  AND profile.user_id = #{trustedUserId, jdbcType=OTHER}
  AND job.user_id = profile.user_id
  AND job.language_profile_id = profile.id
  AND job.model_purpose = #{modelPurpose, jdbcType=VARCHAR}
  AND job.model_operation = #{modelOperation, jdbcType=VARCHAR}
  AND job.workflow_id = #{id, jdbcType=OTHER}
  AND job.workflow_step_id = #{workflowStepId, jdbcType=VARCHAR}
  AND job.workflow_version = #{workflowVersion, jdbcType=BIGINT}
  AND job.provider_id IS NULL
  AND job.model_id IS NULL
  AND job.execution_status = 'CREATED'
  AND job.consumption_status = 'NOT_READY'
  AND job.row_version = 0
RETURNING id, user_id, language_profile_id, model_call_job_id, status,
          workflow_version, row_version, created_at, completed_at

