INSERT INTO planning_run_candidate (run_id, candidate_index, material_id, published_version)
SELECT run.id,
       #{candidateIndex, jdbcType=SMALLINT},
       #{materialId, jdbcType=VARCHAR},
       #{publishedVersion, jdbcType=VARCHAR}
FROM planning_run run
WHERE run.id = #{planningRunId, jdbcType=OTHER}
  AND run.user_id = #{trustedUserId, jdbcType=OTHER}
  AND run.language_profile_id = #{languageProfileId, jdbcType=OTHER}
  AND run.status = 'PENDING'

