SELECT 
FROM planning_run run
WHERE run.id = #{planningRunId, jdbcType=OTHER}
  AND run.user_id = #{trustedUserId, jdbcType=OTHER}
  AND run.language_profile_id = #{languageProfileId, jdbcType=OTHER}

SELECT candidate.candidate_index, candidate.material_id, candidate.published_version
FROM planning_run_candidate candidate
JOIN planning_run run ON run.id = candidate.run_id
WHERE run.id = #{planningRunId, jdbcType=OTHER}
  AND run.user_id = #{trustedUserId, jdbcType=OTHER}
  AND run.language_profile_id = #{languageProfileId, jdbcType=OTHER}
ORDER BY candidate.candidate_index
